const e="iaps-iart-competition",h=2026,t="Built from the organiser's 2026 information sheet. No prize values, entry fee, venue address or marks are printed. Age bands in the template are placeholders; the printed eligibility is the school year. The sheet names the Art Subject Adviser; the name is not captured. The privacy notice link is not printed in full.",o={Title:"iArt Rules & Criteria",Subtitle:"IAPS art competition for member schools",NoticeTitle:"Please Read Before Registering",Notice:"Only full IAPS member schools may enter. Entries cannot be edited, altered or replaced once submitted.",Notes:["Closing time: {{Deadline}}.","Theme for this edition: {{Theme}}."],Sections:[{Key:"general",Title:"About the competition",Items:["iArt is an art competition run by IAPS for its member schools.","All submissions must relate in some way to the theme: {{Theme}}.","The theme is open to the pupils' own interpretation. It is there to make the competition cohesive and to encourage pupils to be imaginative.","There is no set format. Entries can be paintings, drawings or models, of any size, in any medium and with any art supplies.","Pupils are encouraged to make original artwork. Younger pupils may simply paint, draw or create something that reminds them of the theme."]},{Key:"eligibility",Title:"Who can enter",Items:["The school must be a full member of IAPS.","A school may enter only one piece of art per age category (for example one piece for Years 5 & 6, not one from Year 5 and one from Year 6).","The maximum is 5 entries per school, one in each of the five age categories.","Each entry must be the individual work of a single pupil.","The artwork must be created during the 2025-2026 academic year.","Group work is not accepted.","The five age categories are Years 1 & 2, Years 3 & 4, Years 5 & 6, Years 7 & 8 and Years 9, 10 & 11."]},{Key:"registration",Title:"How to enter",Items:["Entries open on {{OpeningDate}}.","Submit entries online with the IAPS website online form. Staff use their own login details.","A member of staff who has not used the IAPS website before must first register using the registration form on the site.","Send two photographs with each entry: the artwork, and the pupil holding or standing alongside their artwork.","Photographs should fill the frame with the artwork as much as possible.","Photographs must be at least 3,000 pixels on the longest edge.","Remove all names, school details and identifying information from the photographs.","IAPS uses these photographs to create the winners' framed prize.","Once submitted, entries cannot be edited, altered or replaced.","The deadline is {{Deadline}}.","Questions: {{OfficeContact}}."]},{Key:"dates",Title:"Timeline",Items:["Competition opens: {{OpeningDate}}.","Submission deadline: {{Deadline}}.","Winners announced: {{WinnersAnnounced}}.","Prizegiving evening: {{Prizegiving}}."]},{Key:"judging",Title:"Judging",Items:["Entries are judged on interpretation of the theme.","Entries are judged on creativity in exploring the theme.","Entries are judged on overall design and presentation.","Entries are also judged on the indefinable quality that draws you in and makes the artwork memorable.","The IAPS Art Subject Adviser shortlists the artwork. A guest judge then selects the winners.","The sheet prints no marks for these criteria."]},{Key:"prizes",Title:"Prizes",Items:["Prizes are awarded for first, second and third place in each age category.","Winners receive an A3 framed picture of their artwork to take home, and a voucher.","The winners of each category are invited to a prizegiving evening, normally held in London, where winning artworks are displayed and prizes are awarded."]},{Key:"conduct",Title:"Permissions and copyright",Items:["By entering, the school gives permission for artwork photographs, pupil photographs and details (full name, school, year group) to be shared with local press, on the IAPS website and on social media, if the artwork is shortlisted.","Copyright of all entries remains with the artist.","For privacy concerns, contact the IAPS Sport and Pupil Experience Team. Read the IAPS privacy notice for further details."]}],Documents:[{Title:"iArt 2026 Competition Information for Schools (PDF)",Url:"https://www.iaps.uk/static/6e198ad6-2d7b-44ce-b54c27370366d07f/iArt-2026-Competition-Information-for-Schools.pdf"}]},i=[{ParticipantType:"Individual",Source:"iArt 2026 Competition Information for Schools",Sections:{About:null,TimeAndFormat:null,Rules:["Each entry is the work of one pupil. Group work is not accepted."],Allowed:null,NotAllowed:null,Judging:null,Points:null,Notes:null},Markdown:`## Rules
- Each entry is the work of one pupil. Group work is not accepted.`}],n=[],r=[{Title:"iArt Artwork",Source:"iArt 2026 Competition Information for Schools",Sections:{About:["An artwork of any medium that relates to the theme: {{Theme}}."],TimeAndFormat:null,Rules:["Paintings, drawings and models are accepted, of any size and with any art supplies.","Send a photograph of the artwork and a photograph of the pupil with the artwork."],Allowed:null,NotAllowed:null,Judging:["Interpretation of the theme.","Creativity in exploring the theme.","Overall design and presentation.","The indefinable quality that makes the artwork memorable."],Points:["Prizes for first, second and third place in each age category."],Notes:null},Markdown:`## About this competition
- An artwork of any medium that relates to the theme: {{Theme}}.

## Rules
- Paintings, drawings and models are accepted, of any size and with any art supplies.
- Send a photograph of the artwork and a photograph of the pupil with the artwork.

## Judging
- Interpretation of the theme.
- Creativity in exploring the theme.
- Overall design and presentation.
- The indefinable quality that makes the artwork memorable.

## Points
- Prizes for first, second and third place in each age category.`}],a=[],s=[{Key:"Theme",Kind:"text",Label:"Competition theme",Value:"Contrast",Source:"iArt 2026 Competition Information for Schools"},{Key:"OpeningDate",Kind:"date",Label:"Entries open",Value:"2026-01-19",Source:"iArt 2026 Competition Information for Schools"},{Key:"Deadline",Kind:"date",Label:"Submission deadline (noon)",Value:"2026-03-20",Source:"iArt 2026 Competition Information for Schools"},{Key:"WinnersAnnounced",Kind:"date",Label:"Winners announced by",Value:"2026-05-19",Source:"iArt 2026 Competition Information for Schools"},{Key:"Prizegiving",Kind:"text",Label:"Prizegiving evening",Value:"June 2026 (more information to follow), normally held in London",Source:"iArt 2026 Competition Information for Schools"},{Key:"OfficeContact",Kind:"contact",Label:"Contact for questions",Value:{Name:"IAPS Sport and Pupil Experience Team",Role:"Competitions contact",Phone:"",WhatsApp:"",Email:"competitions@iaps.uk"},Source:"iArt 2026 Competition Information for Schools"}],l=[{Claim:"Rules, eligibility, timeline, judging and prizes of the IAPS iArt 2026 competition.",SourceType:"Primary - the event's own rules document",Source:"iArt 2026 Competition Information for Schools",Url:"https://www.iaps.uk/static/6e198ad6-2d7b-44ce-b54c27370366d07f/iArt-2026-Competition-Information-for-Schools.pdf"}],d={TemplateKey:e,Year:2026,Note:t,Page:o,ParticipantTypes:i,AgeGroups:n,Competitions:r,CompetitionAgeGroups:a,Variables:s,Evidence:l};export{n as AgeGroups,a as CompetitionAgeGroups,r as Competitions,l as Evidence,t as Note,o as Page,i as ParticipantTypes,e as TemplateKey,s as Variables,h as Year,d as default};
